const X_POSTS_QUERY = 'rc-x-posts';
const X_IMAGE_QUERY = 'rc-x-image';
const YOUTUBE_VIDEOS_QUERY = 'rc-youtube-videos';
const YOUTUBE_IMAGE_QUERY = 'rc-youtube-image';
const PROFILE_DETAILS_QUERY = 'rc-profile-details';
